				out[key] = child
				continue
			}
			out[trailEventCamelKey(key)] = normalizeTrailEventValue(child)
		}
		return out
	case []any:
		for i := range v {
			v[i] = normalizeTrailEventValue(v[i])
		}
	}
	return value
}

